// Code generated by packages/kit-compose/src/organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
/**
 * One entry of a menu: a link to its address, or, without one, its content as text in the same box (the magazine
 * routes nothing, so it shows text). current marks the page the entry stands for (aria-current) either way.
 */
import { type ReactNode } from "react";
import { Box, Inline, Link } from "../compose";
import { urlOf } from "../utils";

export type MenuEntryProps = {
  href?: string;
  current?: boolean;
  variant?: "default" | "muted" | "block";
  size?: "default" | "sm";
  testid?: string;
  block?: boolean;
  className?: string;
  children?: ReactNode;
};

export function MenuEntry({
  href,
  current = false,
  variant = "default",
  size = "default",
  testid,
  block = false,
  className,
  children,
}: MenuEntryProps) {
  return (
    <>
      {href ? (
        <Link
          href={urlOf(href)}
          variant={variant}
          size={size}
          aria-current={(current ? "page" : undefined)}
          className={className}
          data-slot={(testid ?? "menu-entry")}
        >
          {children}
        </Link>
      ) : block ? (
        <Box className={className} aria-current={(current ? "page" : undefined)} data-slot={(testid ?? "menu-entry")}>
          {children}
        </Box>
      ) : (
        <Inline
          className={className}
          aria-current={(current ? "page" : undefined)}
          data-slot={(testid ?? "menu-entry")}
        >
          {children}
        </Inline>
      )}
    </>
  );
}
